// Instagram OAuth — Exchange authorisation code for long-lived token
// Uses Facebook Graph API (Instagram with Instagram Login uses same endpoint)
// NEVER use this.getCredentials() — use $env.VARIABLE_NAME

const body = $input.first().json.body || $input.first().json;
const code = body.code;
const memberEmail = body.member_email || '';
const redirectUri = body.redirect_uri || 'https://brief.one-empire.com/instagram/callback';

if (!code) {
  throw new Error('Missing authorisation code');
}

const appId     = $env.INSTAGRAM_APP_ID;
const appSecret = $env.INSTAGRAM_APP_SECRET;

// Step 1: Exchange code for short-lived token via Facebook OAuth endpoint
const tokenParams = new URLSearchParams({
  client_id:     appId,
  client_secret: appSecret,
  grant_type:    'authorization_code',
  redirect_uri:  redirectUri,
  code:          code
});

let shortTokenData;
try {
  const tokenRes = await $helpers.httpRequest({
    method: 'POST',
    url: 'https://graph.facebook.com/v18.0/oauth/access_token',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: tokenParams.toString()
  });
  shortTokenData = typeof tokenRes === 'string' ? JSON.parse(tokenRes) : tokenRes;
} catch (e) {
  throw new Error('Token exchange failed: ' + e.message);
}

if (shortTokenData.error) {
  throw new Error('Facebook error: ' + (shortTokenData.error.message || JSON.stringify(shortTokenData.error)));
}

const shortToken = shortTokenData.access_token;

// Step 2: Get long-lived token (60 days)
let longTokenData;
try {
  const longTokenRes = await $helpers.httpRequest({
    method: 'GET',
    url: `https://graph.facebook.com/v18.0/oauth/access_token?grant_type=fb_exchange_token&client_id=${appId}&client_secret=${appSecret}&fb_exchange_token=${shortToken}`
  });
  longTokenData = typeof longTokenRes === 'string' ? JSON.parse(longTokenRes) : longTokenRes;
} catch (e) {
  // Fall back to short-lived token if exchange fails
  longTokenData = shortTokenData;
}

const accessToken = longTokenData.access_token || shortToken;
const expiresIn   = longTokenData.expires_in   || shortTokenData.expires_in || 5184000;

// Step 3: Get Instagram Business Account ID and username
let igUserId   = '';
let igUsername = '';
try {
  const meRes = await $helpers.httpRequest({
    method: 'GET',
    url: `https://graph.facebook.com/v18.0/me?fields=id,name,instagram_business_account&access_token=${accessToken}`
  });
  const meData = typeof meRes === 'string' ? JSON.parse(meRes) : meRes;
  if (meData.instagram_business_account) {
    igUserId = meData.instagram_business_account.id;
    // Fetch Instagram username
    try {
      const igRes = await $helpers.httpRequest({
        method: 'GET',
        url: `https://graph.facebook.com/v18.0/${igUserId}?fields=username&access_token=${accessToken}`
      });
      const igData = typeof igRes === 'string' ? JSON.parse(igRes) : igRes;
      igUsername = igData.username || '';
    } catch (e) { /* non-fatal */ }
  } else {
    // Fallback: use Facebook user ID
    igUserId = meData.id || '';
    igUsername = meData.name || '';
  }
} catch (e) {
  // Non-fatal — store token without profile details
}

const now = new Date();
const expiresAt = new Date(now.getTime() + expiresIn * 1000);

return [{
  json: {
    member_email:   memberEmail,
    instagram_id:   igUserId,
    instagram_name: igUsername,
    access_token:   accessToken,
    expires_in:     expiresIn,
    token_stored_at: now.toISOString(),
    token_expires_at: expiresAt.toISOString(),
    is_active: true
  }
}];

// Store Instagram token in Supabase via REST API
// NEVER use this.getCredentials() — use $env.VARIABLE_NAME

const data = $input.first().json;
const supabaseUrl = 'https://gsqcsyepztcmrvzxevhw.supabase.co';
const serviceKey  = $env.SUPABASE_SERVICE_KEY;

if (!data.member_email) {
  throw new Error('member_email is required to store token');
}

const payload = {
  member_email:     data.member_email,
  instagram_id:     data.instagram_id,
  instagram_name:   data.instagram_name,
  access_token:     data.access_token,
  expires_in:       data.expires_in,
  token_stored_at:  data.token_stored_at,
  token_expires_at: data.token_expires_at,
  is_active:        true
};

try {
  const res = await $helpers.httpRequest({
    method: 'POST',
    url: `${supabaseUrl}/rest/v1/instagram_tokens`,
    headers: {
      'Content-Type':  'application/json',
      'apikey':        serviceKey,
      'Authorization': `Bearer ${serviceKey}`,
      'Prefer':        'resolution=merge-duplicates'
    },
    body: JSON.stringify(payload)
  });
  return [{ json: { success: true, message: 'Instagram token stored', member_email: data.member_email } }];
} catch (e) {
  throw new Error('Failed to store token in Supabase: ' + e.message);
}
